/** Note width buckets (world units): half-lane steps from 0.5 to 12.0 lanes. */
export const hitFxBucket = (w: number) => Math.min(23, Math.max(0, Math.floor(w / 0.796667 - 0.5)))

/** Kinds: 0 normal, 1 just, 2 slide, 3 connect, 4 flick, 5 flick left, 6 flick right. Judgement: native 2..6. */
export const hitFxFirst = (kind: number, judgment: number) => {
    if (kind === 0) {
        if (judgment >= 5) return 0.0
        if (judgment === 4) return 192.0
        if (judgment === 3) return 384.0
        if (judgment === 2) return 528.0
    }
    if (kind === 1) {
        if (judgment >= 5) return 600.0
        if (judgment === 4) return 792.0
        if (judgment === 3) return 984.0
        if (judgment === 2) return 1128.0
    }
    if (kind === 2) {
        if (judgment >= 5) return 1200.0
        if (judgment === 4) return 1392.0
        if (judgment === 3) return 1536.0
        if (judgment === 2) return 1680.0
    }
    if (kind === 3) {
        if (judgment >= 5) return 1752.0
        if (judgment === 4) return 1944.0
        if (judgment === 3) return 2088.0
        if (judgment === 2) return 2232.0
    }
    if (kind === 4) {
        if (judgment >= 5) return 2304.0
        if (judgment === 4) return 2496.0
        if (judgment === 3) return 2688.0
        if (judgment === 2) return 2832.0
    }
    if (kind === 5) {
        if (judgment >= 5) return 2976.0
        if (judgment === 4) return 3168.0
        if (judgment === 3) return 3336.0
        if (judgment === 2) return 3480.0
    }
    if (kind === 6) {
        if (judgment >= 5) return 3624.0
        if (judgment === 4) return 3816.0
        if (judgment === 3) return 3984.0
        if (judgment === 2) return 4128.0
    }
    return -1
}

